pub fn HSD_JObjRemove<'a>(ctx: &'a Ctx, jobj: HSD_JObj<'a>) -> HSD_JObj<'a> {
    let __frame = ctx.stack_frame(0x28);
    let mut jobj = jobj;
    let mut child: HSD_JObj<'a> = null(ctx);
    let mut next: HSD_JObj<'a> = null(ctx);
    let mut prev: HSD_JObj<'a> = null(ctx);
    if Handle::is_null(jobj) {
        return null::<HSD_JObj<'a>>(ctx);
    }
    child = (jobj).child();
    if !Handle::is_null(child) {
        (if Handle::is_null((child).next()) {
            ({ () })
        } else {
            fns::__assert(
                ctx,
                cstr(ctx, 0x804d5db0),
                (0x4c0_i32 as u32),
                cstr(ctx, 0x80406940),
            )
        });
    }
    next = (if !Handle::is_null(child) {
        child
    } else {
        (jobj).next()
    });
    prev = fns::HSD_JObjGetPrev(ctx, jobj);
    if !Handle::is_null(prev) {
        (prev).set_next(next);
    } else if !Handle::is_null((jobj).parent()) {
        ((jobj).parent()).set_child(next);
    }
    if (!Handle::is_null(next)) && (Handle::addr(next) == Handle::addr(child)) {
        (next).set_next((jobj).next());
        (next).set_parent((jobj).parent());
    }
    (jobj).set_parent(null::<HSD_JObj<'a>>(ctx));
    (jobj).set_child(null::<HSD_JObj<'a>>(ctx));
    (jobj).set_next(null::<HSD_JObj<'a>>(ctx));
    inl_HSD_JObjUnref_unfused(ctx, jobj);
    return child;
}

